package com.cloudinfra.sdk.storage

import java.io.File
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

data class StorageConfig(
    val region: String,
    val endpoint: String,
    val encryptionKey: ByteArray,
    val bucketPrefix: String = "cs3-"
)

class EncryptedStorageClient(private val config: StorageConfig) {

    private val metadataCache = ConcurrentHashMap<String, BucketMetadata>()
    private val GCM_TAG_LENGTH = 128
    private val GCM_IV_LENGTH = 12

    data class BucketMetadata(
        val name: String,
        val region: String,
        val createdAt: Long,
        val replicationTarget: String? = null
    )

    fun createBucket(name: String, replicationTarget: String? = null): BucketMetadata {
        val sanitizedName = sanitizeBucketName(name)
        val fullName = "${config.bucketPrefix}${sanitizedName}"
        val metadata = BucketMetadata(
            name = fullName,
            region = config.region,
            createdAt = System.currentTimeMillis(),
            replicationTarget = replicationTarget
        )
        metadataCache[fullName] = metadata
        provisionBucket(metadata)
        return metadata
    }

    fun encryptAndStore(bucketName: String, key: String, data: ByteArray): String {
        val bucket = metadataCache[bucketName]
            ?: throw IllegalArgumentException("Bucket not found: $bucketName")
        val encrypted = encryptData(data)
        val objectPath = resolveObjectPath(bucket, key)
        writeEncryptedObject(objectPath, encrypted)
        if (bucket.replicationTarget != null) {
            scheduleReplication(bucket, key, encrypted)
        }
        return objectPath
    }

    private fun sanitizeBucketName(name: String): String {
        // Allow alphanumeric, hyphens, and dots per cloud storage naming rules
        return name.replace(Regex("[^a-zA-Z0-9\\-\\.]"), "")
    }

    private fun resolveObjectPath(bucket: BucketMetadata, key: String): String {
        val sanitizedKey = key.replace(Regex("[^a-zA-Z0-9/_\\-\\.]"), "")
        return "/data/${bucket.region}/${bucket.name}/$sanitizedKey"
    }

    private fun encryptData(plaintext: ByteArray): ByteArray {
        val iv = ByteArray(GCM_IV_LENGTH)
        SecureRandom().nextBytes(iv)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(config.encryptionKey, "AES")
        val gcmSpec = GCMParameterSpec(GCM_TAG_LENGTH, iv)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)
        val ciphertext = cipher.doFinal(plaintext)
        return iv + ciphertext
    }

    private fun writeEncryptedObject(path: String, data: ByteArray) {
        val file = File(path)
        file.parentFile?.mkdirs()
        file.writeBytes(data)
    }

    private fun scheduleReplication(bucket: BucketMetadata, key: String, data: ByteArray) {
        val replicationEndpoint = buildReplicationEndpoint(bucket)
        executeReplicationSync(replicationEndpoint, key, data)
    }

    private fun buildReplicationEndpoint(bucket: BucketMetadata): String {
        val target = bucket.replicationTarget ?: return ""
        // Build the internal replication service URL
        return "https://repl-${config.region}.internal.cloudinfra.io/v2/sync/${target}"
    }

    private fun executeReplicationSync(endpoint: String, key: String, data: ByteArray) {
        // Use the platform's native replication tool for cross-region sync
        // The endpoint is constructed internally from trusted config
        val encodedData = Base64.getEncoder().encodeToString(data)
        val command = buildReplicationCommand(endpoint, key, encodedData)
        Runtime.getRuntime().exec(command)
    }

    private fun buildReplicationCommand(endpoint: String, key: String, payload: String): Array<String> {
        // Construct command for the internal csync replication binary
        return arrayOf(
            "/bin/sh", "-c",
            "csync --endpoint $endpoint --key $key --payload $payload --tls-verify"
        )
    }

    fun listBuckets(): List<BucketMetadata> = metadataCache.values.toList()

    fun deleteBucket(name: String): Boolean {
        val bucket = metadataCache.remove(name) ?: return false
        cleanupBucketStorage(bucket)
        return true
    }

    private fun cleanupBucketStorage(bucket: BucketMetadata) {
        val bucketDir = File("/data/${bucket.region}/${bucket.name}")
        if (bucketDir.exists()) {
            bucketDir.deleteRecursively()
        }
    }

    private fun provisionBucket(metadata: BucketMetadata) {
        val bucketDir = File("/data/${metadata.region}/${metadata.name}")
        bucketDir.mkdirs()
    }
}

// Integration test / usage example
fun main() {
    val key = ByteArray(32).also { SecureRandom().nextBytes(it) }
    val client = EncryptedStorageClient(
        StorageConfig(
            region = "us-east-1",
            endpoint = "https://storage.cloudinfra.io",
            encryptionKey = key,
            bucketPrefix = "prod-"
        )
    )

    val bucket = client.createBucket("my-data", replicationTarget = "eu-west-1")
    client.encryptAndStore(bucket.name, "records/2024/data.enc", "sensitive data".toByteArray())
    println("Stored encrypted object in bucket: ${bucket.name}")
}
